CREATE   PROCEDURE [synapse_ce].[usp_Insert_adobe_emailsend]
AS
BEGIN

	INSERT INTO [synapse_ce].[adobe_emailsend]
	(
		[Id],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[deliveryprioritycode],
		[instancetypecode],
		[prioritycode],
		[isbilled],
		[ismapiprivate],
		[isregularactivity],
		[isworkflowcreated],
		[leftvoicemail],
		[createdby],
		[createdby_entitytype],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[regardingobjectid],
		[regardingobjectid_entitytype],
		[ownerid],
		[ownerid_entitytype],
		[activityid],
		[activitytypecode],
		[adobe_campaignname],
		[adobe_deliveryname],
		[adobe_mirrorpageurl],
		[adobe_senton],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[owneridname],
		[owneridyominame],
		[owningbusinessunitname],
		[regardingobjectidname],
		[subject]
	)
	SELECT
		src.[Id],
		src.[SinkCreatedOn],
		src.[SinkModifiedOn],
		src.[statecode],
		src.[statuscode],
		src.[deliveryprioritycode],
		src.[instancetypecode],
		src.[prioritycode],
		src.[isbilled],
		src.[ismapiprivate],
		src.[isregularactivity],
		src.[isworkflowcreated],
		src.[leftvoicemail],
		src.[createdby],
		src.[createdby_entitytype],
		src.[modifiedby],
		src.[modifiedby_entitytype],
		src.[modifiedonbehalfby],
		src.[modifiedonbehalfby_entitytype],
		src.[owningbusinessunit],
		src.[owningbusinessunit_entitytype],
		src.[owninguser],
		src.[owninguser_entitytype],
		src.[regardingobjectid],
		src.[regardingobjectid_entitytype],
		src.[ownerid],
		src.[ownerid_entitytype],
		src.[activityid],
		src.[activitytypecode],
		src.[adobe_campaignname],
		src.[adobe_deliveryname],
		src.[adobe_mirrorpageurl],
		src.[adobe_senton],
		src.[createdbyname],
		src.[createdbyyominame],
		src.[createdon],
		src.[modifiedbyname],
		src.[modifiedbyyominame],
		src.[modifiedon],
		src.[modifiedonbehalfbyname],
		src.[modifiedonbehalfbyyominame],
		src.[owneridname],
		src.[owneridyominame],
		src.[owningbusinessunitname],
		src.[regardingobjectidname],
		src.[subject]
	FROM [staging_ce].[adobe_emailsend] src
		LEFT JOIN [synapse_ce].[adobe_emailsend] tgt
			ON src.[Id] = tgt.[Id]
	WHERE tgt.[id] IS NULL

END
